def solve(g):
    H=len(g); W=len(g[0])
    out=[row[:] for row in g]
    from collections import Counter
    bg=Counter(v for row in g for v in row).most_common(1)[0][0]
    painted_a=set()
    def fg(rr,cc): return out[rr][cc]==g[rr][cc] and g[rr][cc]!=bg
    for r in range(H):
        row=g[r]
        if all(v!=bg for v in row): continue
        runs=[]; c=0
        while c<W:
            if row[c]!=bg:
                s=c
                while c<W and row[c]!=bg: c+=1
                runs.append((s,c-1))
            else: c+=1
        rightmost=max((c for c in range(W) if row[c]!=bg), default=-1)
        blocked=False
        if rightmost>=0:
            iso=(rightmost==0 or row[rightmost-1]==bg)
            if iso and rightmost<W-1: blocked=True
        apaint=[]
        long_runs=[x for x in runs if x[1]-x[0]+1>=2]
        if long_runs and not blocked:
            end=max(x[1] for x in long_runs)
            if end<W-1:
                for c in range(end+1,W):
                    out[r][c]=1; apaint.append((r,c)); painted_a.add((r,c))
        for (rr,cc) in apaint:
            if rr+1<H and g[rr+1][cc]!=bg and (rr+1,cc) not in painted_a and out[rr+1][cc]==g[rr+1][cc]:
                out[rr+1][cc]=1
        if any(v!=bg for v in row):
            for c in range(W):
                if g[r][c]!=bg and out[r][c]==g[r][c]:
                    if 0<r<H-1 and fg(r-1,c) and fg(r+1,c): out[r][c]=1
    return out

