                other=c_[i]
                for c in range(len(g[0])):
                    if g[r][c]==bg and g[other][c]!=bg:
                        out[r][c]=1; marks.append((r,c))
    return out,marks

def rule_anycol(g,bg):
    """mark bg where ANY row of another band has fg at that column"""
    bs=bands(g,bg); out=[row[:] for row in g]; marks=[]
    for bi,b in enumerate(bs):
        others=[r for bj,c_ in enumerate(bs) if bj!=bi for r in c_]
        for r in b:
            for c in range(len(g[0])):
                if g[r][c]==bg and any(g[o][c]!=bg for o in others):
                    out[r][c]=1; marks.append((r,c))
    return out,marks

